import {subnet,ipToInt,intToIp,rangeInfo,examples,generateQuestion,checkField} from './core.mjs';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let q,topic='mixed',questionIndex=0,revealed=0,solved=false,hadError=false,exploreIP='167.199.170.82';
let progress={solved:0,streak:0};
try {const saved=JSON.parse(localStorage.getItem('subnet-studio-progress-v1'));if(saved && Number.isSafeInteger(saved.solved)&&saved.solved>=0&&Number.isSafeInteger(saved.streak)&&saved.streak>=0) progress=saved;} catch{}
function saveProgress(){try{localStorage.setItem('subnet-studio-progress-v1',JSON.stringify(progress));}catch{$('#storage-note').textContent='Progress lasts for this visit.';}updateStats();}
function updateStats(){$('#stat-solved').textContent=progress.solved;$('#stat-streak').textContent=progress.streak;}
function binaryHTML(ip,prefix){return `<div class="binary-address">${ip.split('.').map((v,oct)=>`<div><div class="octet-label"><span>OCTET ${oct+1}</span><span>${v}</span></div><div class="octet-bits">${Number(v).toString(2).padStart(8,'0').split('').map((bit,j)=>`<span class="bit ${oct*8+j>=prefix?'host':''} ${oct*8+j===prefix?'boundary':''}" title="Bit ${oct*8+j+1}: ${oct*8+j<prefix?'fixed network':'variable host'} bit">${bit}</span>`).join('')}</div></div>`).join('')}</div><div class="bit-legend"><span><i class="legend-box"></i>${prefix} fixed network bits</span><span><i class="legend-box host"></i>${32-prefix} variable host bits</span></div>`;}
function addressVisual(ip,prefix){
 const s=subnet(ip,prefix), oct=Math.min(3,Math.floor(prefix/8)), inOct=prefix-oct*8, jump=2**(8-inOct), count=256/jump;
 const value=Number(ip.split('.')[oct]), active=Math.floor(value/jump), first=Math.max(0,Math.min(active-3,count-8)), last=Math.min(count,first+8), lower=3-oct;
 const blocks=Array.from({length:last-first},(_,j)=>{const i=j+first;return `<div class="block-tile ${i===active?'active':''}" title="Octet ${oct+1}: ${i*jump} through ${(i+1)*jump-1}${lower?`; the following ${lower} octet(s) vary freely`:''}">${i*jump}–${(i+1)*jump-1}<small>${i===active?'YOUR BLOCK':`BLOCK ${i+1}`}</small></div>`;}).join('');
 return `<h3 class="visual-title">The address, in bits</h3><p class="visual-subtitle">${esc(ip)} · /${prefix} fixes the first ${prefix} positions.</p>${binaryHTML(ip,prefix)}<div class="visual-insight"><strong>2<sup>${s.hostBits}</sup> = ${s.total.toLocaleString()}</strong><p><b>${s.hostBits} bits can change.</b><br>Each added network bit halves the block.</p></div><div class="block-label">Octet ${oct+1} · aligned address blocks<span>${count} block${count!==1?'s':''}${count>8?' · 8 shown':''}</span></div><div class="block-map">${blocks}</div><p class="block-caption">${lower?`Each tile spans every combination of the ${lower} following octet${lower>1?'s':''}. `:''}${prefix===24?'All 8 bits in the last octet vary: 0 through 255.':prefix===27?'The first 3 bits of octet 4 are fixed. The final 5 vary, creating 32-address blocks.':`Each tile contains ${s.total.toLocaleString()} addresses. Only the host bits change within one block.`}</p>`;
}
function rangeVisual(question){const r=rangeInfo(question.start,question.end), a=question.start.split('.'),b=question.end.split('.');
 const rows=Number(b[2])-Number(a[2])+1, show=rows<=8 && a.slice(0,2).join('.')===b.slice(0,2).join('.');
 return `<h3 class="visual-title">An address range is continuous</h3><p class="visual-subtitle mono">${esc(question.start)} → ${esc(question.end)}</p>${show?`<div class="range-cells">${Array.from({length:rows},(_,i)=>`<div class="range-cell"><strong>${a[0]}.${a[1]}.${Number(a[2])+i}.*</strong><small>Last octet: ${i===0?a[3]:0}–${i===rows-1?b[3]:255}</small></div>`).join('')}</div>`:''}<p class="block-caption">After .255, the next address is .0 in the next third octet. Count every address, including both endpoints.</p><div style="margin-top:20px">${binaryHTML(question.start,r.prefix)}</div><p class="block-caption">The endpoints share ${r.prefix} fixed bits. Their common prefix gives a covering block; alignment determines whether it matches the range exactly.</p>`;
}
function vlsmVisual(question){return `<h3 class="visual-title">A /24 is your available space</h3><p class="visual-subtitle">256 addresses to divide, with no overlapping subnets.</p><div class="range-cells">${question.alloc.map(r=>`<div class="range-cell"><strong>Network ${r.name}</strong><small>${r.hosts} hosts needed</small></div>`).join('')}</div><div class="range-strip" aria-label="Proportional allocation sizes; the remaining space is unallocated">${question.alloc.map(r=>`<span style="width:${r.total/256*100}%">${r.name}</span>`).join('')}</div><p class="block-caption">Proportional block sizes. The pale space is unallocated. Each allocation must fit its hosts plus the reserved network and broadcast addresses.</p><div class="tip"><strong>Large requests go first.</strong><p>For each request: hosts + 2 → round up to a power of two → find an aligned starting boundary.</p></div>`;}
function loadQuestion(question){
 q=question;questionIndex++;revealed=0;solved=false;hadError=false;
 $('#question-index').textContent=String(questionIndex).padStart(2,'0');
 $('#question-body').innerHTML=`<div class="question-tag">${esc(q.tag)}</div><h2>${esc(q.title)}</h2>${q.kind==='address'?`<div class="question-address">${q.ip}<span>/${q.prefix}</span></div>`:''}<p class="question-lead">${esc(q.lead)}</p>`;
 $('#answer-fields').innerHTML=q.fields.map(f=>`<div class="field" id="field-${f.key}"><label for="answer-${f.key}">${esc(f.label)}</label>${f.type==='choice'?`<select id="answer-${f.key}" data-key="${f.key}" aria-describedby="feedback-${f.key}"><option value="">Choose…</option><option value="yes">Yes</option><option value="no">No</option></select>`:`<input id="answer-${f.key}" data-key="${f.key}" data-type="${f.type}" inputmode="${f.type==='number'?'numeric':f.type==='ip'?'decimal':'text'}" autocomplete="off" spellcheck="false" placeholder="${esc(f.placeholder||'Your answer')}" aria-describedby="feedback-${f.key}">`}<p class="feedback" id="feedback-${f.key}" aria-live="polite"></p></div>`).join('');
 $('#check-summary').textContent='';$('#check-summary').className='check-summary';$('#hint-box').hidden=true;$('#example-select').value='';
 $('#practice-visual').innerHTML=q.kind==='range'?rangeVisual(q):q.kind==='vlsm'?vlsmVisual(q):addressVisual(q.ip,q.prefix);
 $('#check-button').innerHTML='Check answers <span>↗</span>';renderSteps();
 q.fields.forEach(f=>{const input=$(`#answer-${f.key}`);let timer;input.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(()=>{if(input.isConnected&&input.value.trim()){checkOne(f);finishIfCorrect();}},450);});input.addEventListener('change',()=>{clearTimeout(timer);if(input.value.trim()){checkOne(f);finishIfCorrect();}});input.addEventListener('blur',()=>{if(input.isConnected&&input.value.trim())checkOne(f);});});
}
function checkOne(f){const input=$(`#answer-${f.key}`),r=checkField(f,input.value);const wrap=$(`#field-${f.key}`);wrap.classList.remove('correct','incorrect');wrap.classList.add(r.ok?'correct':'incorrect');input.setAttribute('aria-invalid',String(!r.ok));$(`#feedback-${f.key}`).textContent=r.ok?'✓ Correct':r.message;return r;}
function finishIfCorrect(){const all=q.fields.every(f=>checkField(f,$(`#answer-${f.key}`).value).ok);if(!all){if($('#check-summary').classList.contains('success')){$('#check-summary').className='check-summary';$('#check-summary').textContent='Answers changed. Check the edited fields.';$('#check-button').innerHTML='Check answers <span>↗</span>';}return false;}
 if(!solved){solved=true;progress.solved++;progress.streak=(!hadError&&revealed===0)?progress.streak+1:0;saveProgress();}
 $('#check-summary').className='check-summary success';$('#check-summary').textContent=revealed>0?'✓ All correct. Worked through and understood. Ready for another?':'✓ All correct. You’ve found the block. Ready for another?';$('#check-button').innerHTML='All correct <span>✓</span>';return true;}
$('#answer-form').addEventListener('submit',e=>{e.preventDefault();const results=q.fields.map(checkOne);if(!finishIfCorrect()){hadError=true;progress.streak=0;saveProgress();const correct=results.filter(r=>r.ok).length;$('#check-summary').className='check-summary';$('#check-summary').textContent=`${correct} of ${q.fields.length} correct. ${results.some(r=>r.empty)?'Complete the empty fields, then try again.':'You can revise any answer or reveal the next step.'}`;const first=results.findIndex(r=>!r.ok);$(`#answer-${q.fields[first].key}`).focus();}});
function renderSteps(){$('#steps-body').innerHTML=revealed? q.steps.slice(0,revealed).map((s,i)=>`<div class="step"><div class="step-number">${i+1}</div><div><h3>${esc(s.title)}</h3><p>${esc(s.body)}</p></div></div>`).join(''):`<p class="locked-steps">Try it yourself, then uncover the logic one step at a time. Your answers stay in place.</p>`;$('#next-step').hidden=revealed===q.steps.length;$('#next-step').innerHTML=`Reveal step ${revealed+1} <span>↓</span>`;$('#reveal-all').disabled=revealed===q.steps.length;}
$('#next-step').addEventListener('click',()=>{revealed=Math.min(revealed+1,q.steps.length);renderSteps();});$('#reveal-all').addEventListener('click',()=>{revealed=q.steps.length;renderSteps();});
$('#hint-button').addEventListener('click',()=>{const h={address:'Find the host bits first: 32 − prefix. For the network, keep the network bits and turn every host bit to zero. For the broadcast, turn them all to one.',mask:'Each mask octet uses the bit weights 128, 64, 32, 16, 8, 4, 2, 1. Add the weights of the fixed 1-bits, from left to right.',class:'The original prefix is /16. Find b such that 2^b equals the requested number of subnets, then add b to 16.',range:'Count inclusively using end − start + 1. A power-of-two count is only half the test: the start must also be aligned to that block size.',vlsm:'Include 2 reserved addresses for each network. Choose the next power of two that fits, and allocate the largest network first.'};$('#hint-box').textContent=h[q.kind];$('#hint-box').hidden=!$('#hint-box').hidden;});
$('#example-select').innerHTML+=examples.map((e,i)=>`<option value="${i}">${esc(e.label)}</option>`).join('');$('#example-select').addEventListener('change',e=>{if(e.target.value!=='')loadQuestion(examples[Number(e.target.value)].make());});
function newQuestion(){loadQuestion(generateQuestion(topic));}$('#new-question').addEventListener('click',newQuestion);$$('[data-topic]').forEach(b=>b.addEventListener('click',()=>{topic=b.dataset.topic;$$('[data-topic]').forEach(x=>x.classList.toggle('active',x===b));newQuestion();}));
function setView(view){if(!['practice','explore','reference'].includes(view))view='practice';$$('.view').forEach(v=>v.hidden=v.id!==`${view}-view`);$$('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);if(b.dataset.view===view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});$('#view-title').textContent={practice:'Practice lab',explore:'Bit explorer',reference:'Quick reference'}[view];if(view==='explore')renderExplorer();}
$$('[data-view]').forEach(b=>b.addEventListener('click',()=>{location.hash=b.dataset.view;setView(b.dataset.view);}));window.addEventListener('hashchange',()=>setView(location.hash.slice(1)));
function renderExplorer(){const p=Number($('#prefix-slider').value),s=subnet(exploreIP,p);$('#slider-label').textContent=`/${p}`;$('#explore-visual').innerHTML=addressVisual(exploreIP,p);$('#explore-results').innerHTML=[['CIDR block',`${s.network}/${p}`],['Subnet mask',s.mask],['Network address',s.network],['Broadcast address',s.broadcast],['First usable host',s.first],['Last usable host',s.last],['Total addresses',s.total.toLocaleString()],['Usable hosts',s.usable.toLocaleString()]].map(([a,b])=>`<div class="result-row"><span>${a}</span><b>${b}</b></div>`).join('');}
$('#prefix-slider').addEventListener('input',renderExplorer);$('#explorer-form').addEventListener('submit',e=>{e.preventDefault();try{exploreIP=intToIp(ipToInt($('#explore-ip').value));$('#explore-ip').value=exploreIP;$('#explore-error').textContent='';$('#explore-ip').removeAttribute('aria-invalid');renderExplorer();}catch(e){$('#explore-error').textContent=e.message;$('#explore-ip').setAttribute('aria-invalid','true');}});
$('#prefix-table').innerHTML=[16,18,20,24,25,26,27,28,29,30].map(p=>{const s=subnet('0.0.0.0',p);return `<tr><td>/${p}</td><td>${s.mask}</td><td>${s.total.toLocaleString()}</td><td>${s.usable.toLocaleString()}</td></tr>`;}).join('');
updateStats();loadQuestion(examples[0].make());setView(location.hash.slice(1));
